        for (int i = 0; i <= n; ++i) parent[i] = i;
        for (int i = 0; i < (int)edges.size(); ++i) {
            if (i == skip) continue;
            int ru = find(edges[i][0]), rv = find(edges[i][1]);
            if (ru == rv) return false;
            parent[ru] = rv;
