class Solution {
public:
    int largestIsland(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<int>> label(n, vector<int>(n, 0));
        vector<int> area(1, 0);
        int cur = 0;
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] != 1 || label[i][j] != 0) continue;
                ++cur;
                label[i][j] = cur;
                vector<pair<int, int>> st{{i, j}};
                int size = 0;
                while (!st.empty()) {
                    pair<int, int> c = st.back();
                    st.pop_back();
                    int x = c.first, y = c.second;
                    ++size;
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 1
                                && label[nx][ny] == 0) {
                            label[nx][ny] = cur;
                            st.push_back({nx, ny});
                        }
                    }
                }
                area.push_back(size);
            }
        int best = 0;
        for (int v : area) best = max(best, v);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] != 0) continue;
                vector<int> seen;
                int total = 1;
                for (int k = 0; k < 4; ++k) {
                    int x = i + dx[k], y = j + dy[k];
                    if (x < 0 || x >= n || y < 0 || y >= n) continue;
                    int lab = label[x][y];
                    if (lab == 0) continue;
                    bool dup = false;
                    for (int s : seen)
                        if (s == lab) dup = true;
                    if (!dup) {
                        seen.push_back(lab);
                        total += area[lab];
                    }
                }
                if (total > best) best = total;
            }
        return best;
    }
};

