class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
        const int INF = 1e9;
        vector<vector<int>> d(n, vector<int>(n, INF));
        for (int i = 0; i < n; ++i) d[i][i] = 0;
        for (auto& e : edges) {
            d[e[0]][e[1]] = e[2];
            d[e[1]][e[0]] = e[2];
        }
        for (int p = 0; p < n; ++p)
            for (int i = 0; i < n; ++i) {
                if (d[i][p] == INF) continue;
                for (int j = 0; j < n; ++j)
                    if (d[i][p] + d[p][j] < d[i][j]) d[i][j] = d[i][p] + d[p][j];
            }
        int best = n + 1, ans = 0;
        for (int i = 0; i < n; ++i) {
            int cnt = 0;
            for (int j = 0; j < n; ++j)
                if (i != j && d[i][j] <= distanceThreshold) ++cnt;
            if (cnt <= best) {
                best = cnt;
                ans = i;
            }
        }
        return ans;
    }
};

